/**
 * @param {import('gorules').Input} input
 */
const CONFIG = {
  LIFE: {
    questions: [
      { questionId: 'dateOfDeath', questionText: 'Date of death', fieldType: 'date' },
      { questionId: 'hospital', questionText: 'Hospital/place', fieldType: 'text' },
      { questionId: 'causeOfDeath', questionText: 'Cause of death', fieldType: 'dropdown' },
      { questionId: 'nomineeRelation', questionText: 'Nominee relationship', fieldType: 'dropdown' }
    ],
    requiredDocuments: ['Death Certificate', 'Policy Bond', 'ID Proof (Nominee)', 'Hospital / Medical Record']
  },
  MEDICAL: {
    questions: [
      { questionId: 'admissionDate', questionText: 'Date of admission', fieldType: 'date' },
      { questionId: 'hospital', questionText: 'Hospital name', fieldType: 'text' },
      { questionId: 'diagnosis', questionText: 'Diagnosis', fieldType: 'text' }
    ],
    requiredDocuments: ['Discharge Summary', 'Hospital Bill', 'Policy Bond', 'ID Proof']
  },
  MOTOR: {
    questions: [
      { questionId: 'incidentDate', questionText: 'Date of incident', fieldType: 'date' },
      { questionId: 'incidentType', questionText: 'Type of incident', fieldType: 'dropdown' }
    ],
    requiredDocuments: ['RC Copy', 'Driving License', 'Repair Estimate']
  },
  TRAVEL: {
    questions: [
      { questionId: 'tripDate', questionText: 'Date of trip', fieldType: 'date' },
      { questionId: 'issueType', questionText: 'What happened', fieldType: 'dropdown' }
    ],
    requiredDocuments: ['Boarding Pass', 'Airline Delay Certificate', 'Policy Bond']
  }
};

const handler = (input) => {
  const config = CONFIG[input.claimType];
  if (!config) {
    throw new Error('Unknown claim type: ' + input.claimType);
  }
  return {
    claimType: input.claimType,
    questions: config.questions,
    requiredDocuments: config.requiredDocuments
  };
};
